var FI=[['Manzanilla','Matricaria chamomilla','Flores','Infusión','Suave y dulzón','Su nombre viene de su aroma, que recuerda a la manzana.'],['Menta','Mentha × piperita','Hojas','Infusión','Fresco, mentolado','La menta piperita es un cruce natural entre dos mentas.'],['Tilo','Tilia spp.','Flores y brácteas','Infusión','Floral, dulce','Se usan las flores junto con la hojita alargada que las acompaña.'],['Cedrón','Aloysia citrodora','Hojas','Infusión','A limón','Es nativo de Sudamérica, Argentina incluida.'],['Peperina','Minthostachys verticillata','Hojas y tallos','Infusión o en el mate','Mentolado','Crece en las sierras del centro y el noroeste argentino.'],['Hibiscus','Hibiscus sabdariffa','Cálices','Infusión, fría o caliente','Ácido y frutal','En México la bebida se llama “agua de Jamaica”.'],['Jengibre','Zingiber officinale','Rizoma','Decocción','Picante y fresco','Se puede usar fresco, seco o en polvo.'],['Canela','Cinnamomum verum','Corteza','Decocción','Dulce y especiado','La de Ceilán es más fina y quebradiza que la cassia.'],['Melisa','Melissa officinalis','Hojas','Infusión','Limón suave','Su nombre viene del griego “abeja”: sus flores las atraen.'],['Lavanda','Lavandula angustifolia','Flores','Infusión, en poca cantidad','Floral intenso','También se usa en repostería, con mucha moderación.'],['Romero','Salvia rosmarinus','Hojas','Infusión o en la cocina','Resinoso','Desde 2017 los botánicos lo clasifican dentro del género Salvia.'],['Anís','Pimpinella anisum','Frutos (semillas)','Infusión, con las semillas apenas machacadas','Dulce, anisado','No es lo mismo que el anís estrellado, que viene de un árbol asiático.']];
var TI=[['Mate','El agua ideal está entre 70 y 80 °C: si hierve, la yerba se lava antes.'],['Té verde','Agua de 70 a 80 °C y 2 o 3 minutos de reposo, para que no amargue.'],['Frutos secos','Guardalos en frasco hermético, en un lugar fresco y oscuro. En verano, mejor en la heladera.'],['Especias','Las enteras conservan el aroma mucho más que las molidas: molelas en el momento.'],['Legumbres','Dejarlas en remojo la noche anterior acorta la cocción.'],['Semillas','Tostá sésamo o girasol 2 o 3 minutos en una sartén seca: cambian por completo de sabor.'],['Palta y manzana','Un chorrito de limón evita que se pongan negras una vez cortadas.'],['Chía','En agua forma un gel en unos 15 minutos: sirve para hacer pudines.'],['Hierbas secas','Duran más en frascos de vidrio, lejos de la luz y la humedad.'],['Quinoa','Enjuagala y cocinala con el doble de agua, unos 15 minutos.'],['Miel','Agregala cuando la infusión ya no esté hirviendo, así conserva su aroma.'],['Yerba con polvo','Tapá la boca del mate y sacudilo antes de cebar.']];
