/* si la planilla de contenido está disponible, manda ella (incluye todo lo de arriba más lo cargado por formulario) */
var KY=function(x){return String(typeof x==='string'?x:x[0]).toLowerCase().replace(/[^a-z0-9áéíóúñ]+/g,'')};
/* planilla + código: se suman (sin repetir), así lo nuevo del código también aparece */
var SD=window.dnSheet&&window.dnSheet.data;if(SD)Object.keys(C).forEach(function(k){if(SD[k]&&SD[k].length){var h={},o=SD[k].slice();o.forEach(function(x){h[KY(x)]=1});C[k].forEach(function(x){if(!h[KY(x)]){h[KY(x)]=1;o.push(x)}});C[k]=o}});
/* distinto en cada visita: primero lo que esta persona todavía no vio (se recuerda en su navegador) */
var VK='dnVisto1',V={};try{V=JSON.parse(localStorage.getItem(VK))||{}}catch(e){}
function fresh(k,A){SH(A);var s=V[k]||[],h={};s.forEach(function(x){h[x]=1});var a=[],b=[];A.forEach(function(x){(h[KY(x)]?b:a).push(x)});return a.concat(b)}
var tm=0;function mark(k,x){if(!x)return;var s=V[k]||(V[k]=[]),y=KY(x);if(s.indexOf(y)>=0)return;s.push(y);var max=Math.max(4,Math.floor((C[k]?C[k].length:56)*.7));while(s.length>max)s.shift();clearTimeout(tm);tm=setTimeout(function(){try{localStorage.setItem(VK,JSON.stringify(V))}catch(e){}},400)}
window.dnVisto={mark:mark,key:KY,fresh:function(k,A){return fresh(k,A)}};
